  id: 'content-processing-workflow',
  description: 'Validates and enhances content',
  inputSchema: z.object({
    content: z.string(),
    type: z.enum(['article', 'blog', 'social']).default('article'),
  }),
  outputSchema: z.object({
    content: z.string(),
    type: z.string(),
    wordCount: z.number(),
    metadata: z.object({
      readingTime: z.number(),
      difficulty: z.enum(['easy', 'medium', 'hard']),
      processedAt: z.string(),
    }),
  }),
})
  .then(validateContentStep)
  .then(enhanceContentStep)
  .commit()
```

--------------------------------

### Configure retries in createWorkflow

Source: https://github.com/mastra-ai/mastra/blob/main/docs/src/content/en/integrations/deploy/inngest.mdx

Re-invokes the workflow up to 3 times after a failed request, skipping completed steps. `retries` defaults to 0; step-level errors use `retryConfig` or the step's `retries` option instead.

```typescript
const workflow = createWorkflow({
  id: 'long-running-workflow',
  inputSchema: z.object({ jobId: z.string() }),
  outputSchema: z.object({ done: z.boolean() }),
  steps: [longRunningStep],
  // Re-invoke up to 3 times after a failed request
  retries: 3,
})
```

--------------------------------

### Run a workflow with .start()

Source: https://github.com/mastra-ai/mastra/blob/main/docs/src/content/en/docs/workflows/overview.mdx

Create a run instance with `createRun()`, then call `.start()` with `inputData` matching the workflow's `inputSchema`. The workflow executes all steps and returns the final result.

```typescript
const run = await testWorkflow.createRun()

const result = await run.start({
  inputData: {
    message: 'Hello world',
  },
})

if (result.status === 'success') {
  console.log(result.result)
}
```

--------------------------------

### Create a workflow step with createStep using Zod schemas

Source: https://github.com/mastra-ai/mastra/blob/main/docs/src/content/en/docs/workflows/overview.mdx

Defines a step with `createStep`, using Zod `inputSchema` and `outputSchema` and an `execute` function that uppercases the input message. Place in `src/mastra/workflows/test-workflow.ts`.

```typescript
import { createStep } from '@mastra/core/workflows'
import { z } from 'zod'

const step1 = createStep({
  id: 'step-1',
  inputSchema: z.object({
    message: z.string(),
  }),
  outputSchema: z.object({
    formatted: z.string(),
  }),
  execute: async ({ inputData }) => {
    const { message } = inputData

    return {
      formatted: message.toUpperCase(),
    }
  },
})
```

--------------------------------

### Chain workflow steps sequentially with .then()

Source: https://github.com/mastra-ai/mastra/blob/main/docs/src/content/en/docs/workflows/control-flow.mdx

Use .then() to run steps in order so each step can access the previous step's output. The first step's inputSchema must match the workflow's inputSchema, and each step's outputSchema must match the next step's inputSchema.

```typescript
import { createWorkflow, createStep } from '@mastra/core/workflows'
import { z } from 'zod'

const step1 = createStep({
  inputSchema: z.object({
    message: z.string(),
  }),
  outputSchema: z.object({
    formatted: z.string(),
  }),
})

const step2 = createStep({
  inputSchema: z.object({
    formatted: z.string(),
  }),
  outputSchema: z.object({
    emphasized: z.string(),
  }),
})

export const testWorkflow = createWorkflow({
  inputSchema: z.object({
    message: z.string(),
  }),
  outputSchema: z.object({
    emphasized: z.string(),
  }),
})
  .then(step1)
  .then(step2)
  .commit()
```

